{"code": "import os
import numpy as np
from PIL import Image
import shutil

# Create backup directories
for dir_path in ['data_small/Training', 'data_small/Testing']:
    backup_dir = dir_path + '_backup'
    if os.path.exists(dir_path):
        if os.path.exists(backup_dir):
            shutil.rmtree(backup_dir)
        shutil.copytree(dir_path, backup_dir)
        print(f"Backed up {dir_path} to {backup_dir}")

# Function to create a dummy image
def create_dummy_image(path, size=(224, 224)):
    # Create a random image
    img_array = np.random.randint(0, 255, (*size, 3), dtype=np.uint8)
    img = Image.fromarray(img_array)
    img.save(path)

# Replace all "images" with actual dummy images
for base_dir in ['data_small/Training', 'data_small/Testing']:
    for class_dir in os.listdir(base_dir):
        class_path = os.path.join(base_dir, class_dir)
        if os.path.isdir(class_path):
            for file in os.listdir(class_path):
                file_path = os.path.join(class_path, file)
                if os.path.isfile(file_path):
                    create_dummy_image(file_path)
            print(f"Created dummy images in {class_path}")

print("\nDone creating dummy images")"}

